<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';admin_required();
$id=max(1,scalar_int($_GET['id']??0));$stmt=db()->prepare("SELECT file_name FROM backup_runs WHERE id=? AND status='completed'");$stmt->execute([$id]);$name=(string)$stmt->fetchColumn();if($name===''||basename($name)!==$name){http_response_code(404);exit('فایل بکاپ پیدا نشد.');}$directory=realpath(backup_directory());$path=realpath(backup_directory().'/'.$name);if($directory===false||$path===false||!str_starts_with($path,$directory.DIRECTORY_SEPARATOR)||!is_file($path)){http_response_code(404);exit('فایل بکاپ پیدا نشد.');}admin_audit_event('backup_downloaded','backup',$id,['file_name'=>$name]);while(ob_get_level()>0)ob_end_clean();header('Content-Type: application/octet-stream');header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="backup.'.pathinfo($name,PATHINFO_EXTENSION).'"; filename*=UTF-8\'\''.rawurlencode($name));header('Cache-Control: no-store, private');header('X-Content-Type-Options: nosniff');readfile($path);exit;
